-- 009_level_costs.sql — pokemon_gacha
-- =====================================================================
-- BAREME XP COMPLET (niveaux 1 a 500)
--
-- level_costs.xp_required = XP CUMULE pour ATTEINDRE ce niveau.
-- Increment entre deux niveaux : 22.4 * n^1.5 (arrondi).
--
-- Calibrage : 1 bonbon = 100 XP (game_settings.candy_xp_value),
-- 1 combat = 10 bonbons -> un pokemon niveau 1 -> 500 demande
-- ~499 600 bonbons, soit ~49 960 combats.
--
-- Quelques reperes (XP cumule / bonbons) :
--   niveau  10 :        2 486 /      25
--   niveau 100 :      884 829 /   8 848
--   niveau 250 :    8 810 154 /  88 102
--   niveau 500 :   49 962 768 / 499 628
--
-- La table remplace l'ancien echantillon (niveaux 1 a 10 du schema
-- initial) : DELETE puis INSERT complet. REJOUABLE.
-- =====================================================================

USE pokemon_gacha;

DELETE FROM level_costs WHERE level > 0;

